sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var today = new Date();
    today.setHours(0, 0, 0, 0);

    var startDate = new Date(newValue);
    startDate.setHours(0, 0, 0, 0);

    if (startDate < today) {
        //   alert("inside past date check");

        g_form.showFieldMsg('flight_start_date', 'Flight Start Date must be today or a future date.', 'error');
        //   alert("below");
        //   g_form.setValue('flight_start_date', '');
    }
}
